const $ = s => document.querySelector(s);
let state={name:'Aprendiz',goal:10,done:[],dates:[]};
try{state={...state,...JSON.parse(localStorage.getItem('codiva-progress')||'{}')}}catch{}
const courses=[
 {id:'html',name:'HTML & CSS',desc:'Dê vida às suas primeiras páginas web.',icon:'&lt;/&gt;',type:'Web',tag:'COMECE POR AQUI',lessons:[
 {title:'Seu primeiro HTML',intro:'HTML organiza o conteúdo de uma página. A tag <h1> representa seu título principal.',code:'<h1>Olá, mundo!</h1>',question:'Qual tag cria um título principal?',options:['<p>','<h1>','<img>'],answer:1,explain:'Isso! <h1> representa o título principal. <p> cria um parágrafo e <img> insere uma imagem.'},
 {title:'Um toque de cor',intro:'CSS define o estilo dos elementos. A propriedade color altera a cor do texto.',code:'h1 {\n  color: purple;\n}',question:'Qual propriedade altera a cor do texto?',options:['color','font-size','background'],answer:0,explain:'color altera a cor do texto. background define o fundo.'},
 {title:'Conectando páginas',intro:'Links levam você a outras páginas. A tag <a> usa href para definir o destino.',code:'<a href="sobre.html">Sobre nós</a>',question:'Qual atributo define o destino de um link?',options:['src','class','href'],answer:2,explain:'href indica para onde o link leva. Você completou os fundamentos de HTML e CSS deste protótipo!'}]},
 {id:'js',name:'JavaScript',desc:'Transforme ideias em interações.',icon:'JS',type:'Web',lessons:[
 {title:'Guardando informações',intro:'Uma variável guarda um valor. Use let quando esse valor puder mudar.',code:'let pontos = 10;\npontos = 20;',question:'Qual é o valor final de pontos?',options:['10','20','30'],answer:1,explain:'A segunda linha substitui o valor 10 por 20.'},
 {title:'Tomando decisões',intro:'Um if executa código quando uma condição é verdadeira.',code:'let idade = 18;\nif (idade >= 18) {\n  console.log("Pode entrar");\n}',question:'Qual mensagem aparece no console?',options:['Pode entrar','Não pode entrar','Nenhuma mensagem'],answer:0,explain:'18 é maior ou igual a 18, então a condição é verdadeira.'},
 {title:'Sua primeira função',intro:'Funções agrupam instruções e podem devolver um resultado com return.',code:'function dobro(numero) {\n  return numero * 2;\n}\ndobro(4);',question:'Qual valor dobro(4) devolve?',options:['2','4','8'],answer:2,explain:'4 multiplicado por 2 é 8. Você concluiu esta trilha inicial!'}]},
 {id:'py',name:'Python',desc:'Comece simples. Vá cada vez mais longe.',icon:'Py',type:'Dados',lessons:[
 {title:'Olá, Python!',intro:'print() exibe informações. Textos ficam entre aspas.',code:'print("Olá, mundo!")',question:'O que esse código exibe?',options:['Olá, mundo!','print','Uma mensagem de erro'],answer:0,explain:'print exibe o texto que está entre aspas.'},
 {title:'Trabalhando com listas',intro:'Listas guardam vários valores. O primeiro item tem índice 0.',code:'linguagens = ["Python", "JavaScript", "HTML"]\nprint(linguagens[0])',question:'Qual item será exibido?',options:['HTML','JavaScript','Python'],answer:2,explain:'O índice 0 aponta para o primeiro item: Python.'},
 {title:'Repetindo com for',intro:'Um laço for percorre os elementos de uma sequência.',code:'for numero in [1, 2, 3]:\n    print(numero)',question:'Quantas vezes print será executado?',options:['1 vez','3 vezes','4 vezes'],answer:1,explain:'Uma execução para cada um dos três itens da lista.'}]},
 {id:'logic',name:'Lógica de programação',desc:'Aprenda a pensar como quem programa.',icon:'{ }',type:'Fundamentos',lessons:[
 {title:'Passo a passo',intro:'Um algoritmo é uma sequência de passos para resolver um problema.',code:'1. Receber dois números\n2. Somar os números\n3. Mostrar o resultado',question:'O que esse algoritmo faz?',options:['Multiplica dois números','Soma dois números','Ordena uma lista'],answer:1,explain:'A sequência recebe os valores, calcula a soma e apresenta o resultado.'},
 {title:'Verdadeiro ou falso',intro:'Uma condição pode ser verdadeira ou falsa. O operador > compara dois valores.',code:'pontos = 15\npontos > 10',question:'A condição é verdadeira ou falsa?',options:['Verdadeira','Falsa','Não é possível saber'],answer:0,explain:'15 é maior que 10, então a condição é verdadeira.'},
 {title:'Encontrando padrões',intro:'Identificar padrões ajuda a construir soluções que podem ser repetidas.',code:'2, 4, 6, 8, ...',question:'Qual número continua o padrão?',options:['9','12','10'],answer:2,explain:'A sequência soma 2 a cada passo. O próximo número é 10.'}]}];
let currentView='inicio',activeCourse=null,activeLesson=0,selection=null,checked=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dayKey=()=>new Date().toLocaleDateString('sv-SE');
const key=(c,i)=>c.id+'-'+i;
const count=c=>c.lessons.filter((_,i)=>state.done.includes(key(c,i))).length;
const total=()=>state.done.length;
function save(){try{localStorage.setItem('codiva-progress',JSON.stringify(state))}catch{}}
function streak(){let n=0,d=new Date();if(!state.dates.includes(dayKey()))d.setDate(d.getDate()-1);while(state.dates.includes(d.toLocaleDateString('sv-SE'))){n++;d.setDate(d.getDate()-1)}return n}
function chrome(){ $('#header-xp').textContent=total()*20;$('#streak').textContent=streak();document.querySelector('.profile strong').textContent=state.name;document.querySelectorAll('.avatar').forEach(e=>e.textContent=state.name[0]?.toUpperCase()||'A');document.querySelectorAll('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===currentView))}
function card(c){const n=count(c);return `<button class="course" data-course="${c.id}"><div class="course-top"><span class="course-icon ${c.id}">${c.icon}</span><span class="badge">Iniciante</span></div><h3>${c.name}</h3><p>${c.desc}</p><div class="progress"><span style="width:${n/3*100}%"></span></div><div class="course-bottom"><span>${n} de 3 lições</span><span>${Math.round(n/3*100)}%</span></div></button>`}
function home(){const next=courses.find(c=>count(c)<3)||courses[0];const i=Math.max(0,next.lessons.findIndex((_,i)=>!state.done.includes(key(next,i))));const minutes=state.dates.includes(dayKey())?state.todayMinutes||0:0;const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(d.getDay()+6)%7+i);return `<div class="day ${state.dates.includes(d.toLocaleDateString('sv-SE'))?'done':''}"><span>${state.dates.includes(d.toLocaleDateString('sv-SE'))?'✓':'·'}</span>${['S','T','Q','Q','S','S','D'][i]}</div>`}).join('');return `<div class="greeting"><div><div class="eyebrow">CADA LINHA É UM NOVO COMEÇO</div><h1>Olá, ${esc(state.name)} <span style="font-size:25px">✌️</span></h1><p class="intro">Que tal dar mais um passo na sua jornada hoje?</p></div><span class="datepill">No seu ritmo, todos os dias</span></div><div class="columns"><div><section class="hero"><div class="hero-content"><div class="eyebrow">${total()?'CONTINUE DE ONDE PAROU':'SUA JORNADA COMEÇA AQUI'}</div><h2>Pequenos passos.<br>Grandes possibilidades.</h2><p>Aprenda programação em português, uma lição de cada vez. Você não precisa saber nada para começar.</p><button class="primary" data-start="${next.id}" data-index="${i}">${total()?'Continuar aprendendo':'Começar a aprender'} <span>→</span></button></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="code-window"><div class="dots">•••</div><pre>&lt;h1&gt;\n  Olá, mundo!\n&lt;/h1&gt;</pre></div><div class="floating-code">&lt;/&gt;</div></div></section><div class="section-head"><h2>Um caminho para cada ideia</h2><button class="text-button" data-view="trilhas">Ver todas as trilhas →</button></div><div class="course-grid">${courses.map(card).join('')}</div><section class="challenge"><div class="challenge-icon">⌨</div><div><h3>Sua dose diária de código</h3><p>Um desafio rápido para colocar a cabeça para funcionar.</p></div><button class="outline" data-view="pratica">Praticar agora →</button></section></div><div class="right-col"><section class="panel"><div class="panel-title"><h3>Sua meta diária</h3><span class="target">◎</span></div><p>Consistência vale mais que pressa.</p><div class="ring-wrap"><div class="ring" style="--angle:${Math.min(minutes/state.goal,1)*360}deg"><span>${Math.min(Math.round(minutes/state.goal*100),100)}%</span></div><div class="ring-info"><strong>${minutes} de ${state.goal} min</strong><p>Tempo estimado pelas lições</p></div></div><div class="days">${week}</div></section><section class="panel"><div class="panel-title"><h3>Pequenas vitórias</h3><span style="color:#e1b96c">✦</span></div><p style="margin:17px 0"><strong style="font-size:25px;color:var(--ink)">${total()*20}</strong> XP conquistados</p><div class="progress"><span style="width:${Math.min(total()*20/100*100,100)}%"></span></div><p style="margin-top:10px">${Math.max(100-total()*20,0)} XP para sua conquista de 100 XP</p></section><section class="panel tip"><div class="eyebrow">UMA IDEIA PARA LEVAR COM VOCÊ</div><h3>Todo programador já escreveu seu primeiro “Olá, mundo!”.</h3><p>Errar faz parte. Testar de novo também. O importante é continuar curioso.</p><div class="tip-code">console.log("Eu consigo!");</div></section></div></div>`}
function render(view='inicio'){currentView=view;const titles={inicio:'Meu aprendizado',trilhas:'Explorar trilhas',pratica:'Praticar',conquistas:'Conquistas',perfil:'Meu perfil'};$('#breadcrumb').textContent=titles[view]||'Sua trilha';let html='';if(view==='inicio')html=home();if(view==='trilhas')html=`<div class="eyebrow">ENCONTRE SEU PRÓXIMO PASSO</div><h1>O que você quer criar?</h1><p class="intro">Escolha uma trilha e aprenda na prática. Todas começam do zero.</p><div class="filter"><button class="active" data-filter="Todas">Todas</button>${['Web','Dados','Fundamentos'].map(x=>`<button data-filter="${x}">${x}</button>`).join('')}</div><div class="course-grid" id="catalog">${courses.map(card).join('')}</div>`;if(view==='pratica')html=`<div class="eyebrow">APRENDER. TESTAR. REPETIR.</div><h1>Coloque suas ideias em prática.</h1><p class="intro">Revise um conceito rápido. Você pode repetir os exercícios quantas vezes quiser.</p><div class="section-head"><h2>Escolha seu desafio</h2></div><div class="course-grid">${courses.map(c=>`<button class="course" data-start="${c.id}" data-index="${Math.min(count(c),2)}"><span class="course-icon ${c.id}">${c.icon}</span><h3>${c.name}</h3><p>Um exercício guiado · cerca de 3 minutos</p><span class="text-button">Resolver desafio →</span></button>`).join('')}</div>`;if(view==='conquistas')html=`<div class="eyebrow">CELEBRE CADA PASSO</div><h1>Seu esforço vira conquista.</h1><p class="intro">${total()} lições concluídas · ${total()*20} XP · ${streak()} dias seguidos</p><div class="achievements">${[{title:'Primeira linha',text:'Conclua sua primeira lição.',ok:total()>0,icon:'✦'},{title:'Trilha completa',text:'Conclua as 3 lições de uma trilha.',ok:courses.some(c=>count(c)===3),icon:'⚑'},{title:'Curiosidade sem limites',text:'Acumule 100 XP estudando.',ok:total()>=5,icon:'♧'}].map(a=>`<div class="achievement ${a.ok?'':'locked'}"><div class="medal">${a.icon}</div><h3>${a.title}</h3><p>${a.text}</p><span class="badge">${a.ok?'Conquistada ✓':'Em construção'}</span></div>`).join('')}</div>`;if(view==='perfil')html=`<div class="eyebrow">NO SEU RITMO</div><h1>Vamos deixar com a sua cara.</h1><p class="intro">Seus dados e progresso ficam salvos neste navegador.</p><form id="settings" class="empty-card settings"><label for="name">Como podemos chamar você?</label><input id="name" name="name" maxlength="30" required value="${esc(state.name)}"><label for="goal">Sua meta diária</label><select id="goal" name="goal">${[5,10,15,20].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} minutos por dia</option>`).join('')}</select><button class="primary">Salvar preferências</button><p class="save-message" id="saved" aria-live="polite"></p></form>`;$('#content').innerHTML=html;chrome()}
function detail(id){activeCourse=courses.find(c=>c.id===id);currentView='trilhas';$('#breadcrumb').textContent='Explorar trilhas / '+activeCourse.name;$('#content').innerHTML=`<button class="text-button back" data-view="trilhas">← Voltar às trilhas</button><div class="eyebrow">TRILHA PARA INICIANTES</div><h1>${activeCourse.name}</h1><p class="intro">${activeCourse.desc}</p><p class="detail-meta">3 lições interativas · cerca de 9 minutos · ${count(activeCourse)} concluídas</p><div class="lesson-list">${activeCourse.lessons.map((l,i)=>`<div class="lesson-row"><span class="lesson-number">${state.done.includes(key(activeCourse,i))?'✓':i+1}</span><div><h3>${l.title}</h3><p>Explicação + exercício · 20 XP na primeira conclusão</p></div><button class="outline" data-start="${id}" data-index="${i}">${state.done.includes(key(activeCourse,i))?'Revisar':'Começar'} →</button></div>`).join('')}</div>`;chrome()}
function start(id,i){activeCourse=courses.find(c=>c.id===id);activeLesson=Number(i);selection=null;checked=false;lessonRender();if(!$('#lesson').open)$('#lesson').showModal()}
function lessonRender(){const l=activeCourse.lessons[activeLesson];$('#lesson-content').innerHTML=`<div class="lesson-head"><span class="lesson-step">${activeCourse.name.toUpperCase()} · LIÇÃO ${activeLesson+1} DE 3</span><button class="close" data-close aria-label="Fechar lição">×</button></div><h2>${l.title}</h2><p style="color:var(--muted);font-size:13px">${esc(l.intro)}</p><pre class="lesson-code">${esc(l.code)}</pre><strong>${l.question}</strong><div class="answers">${l.options.map((o,i)=>`<button class="answer ${selection===i?'selected':''}" data-answer="${i}" ${checked?'disabled':''}>${esc(o)}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div><button class="primary" id="check">Verificar resposta →</button>`}
function complete(){const k=key(activeCourse,activeLesson);const fresh=!state.done.includes(k);if(fresh){if(!state.dates.includes(dayKey())){state.todayMinutes=0;state.dates.push(dayKey())}state.todayMinutes=(state.todayMinutes||0)+3;state.done.push(k);save()}$('#lesson-content').innerHTML=`<div class="lesson-head"><span class="lesson-step">PEQUENA VITÓRIA, GRANDE PASSO</span><button class="close" data-close aria-label="Fechar">×</button></div><div class="success"><div class="success-icon">✦</div><h2>${fresh?'Mais uma conquista!':'Revisão concluída!'}</h2><p style="color:var(--muted)">${fresh?'Você ganhou 20 XP. Continue construindo seu futuro, uma linha por vez.':'Revisar ajuda a fixar. O XP desta lição já foi conquistado.'}</p><button class="primary" ${activeLesson<2?`data-start="${activeCourse.id}" data-index="${activeLesson+1}"`:'data-close'}>${activeLesson<2?'Próxima lição →':'Voltar ao aprendizado'}</button></div>`;if(currentView==='trilhas')detail(activeCourse.id);else render(currentView)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){render(b.dataset.view);window.scrollTo(0,0)}if(b.dataset.course)detail(b.dataset.course);if(b.dataset.start)start(b.dataset.start,b.dataset.index||0);if(b.hasAttribute('data-close'))$('#lesson').close();if(b.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));$('#catalog').innerHTML=courses.filter(c=>b.dataset.filter==='Todas'||c.type===b.dataset.filter).map(card).join('')}if(b.dataset.answer!==undefined&&!checked){selection=Number(b.dataset.answer);document.querySelectorAll('.answer').forEach(x=>x.classList.toggle('selected',Number(x.dataset.answer)===selection))}if(b.id==='check'){const l=activeCourse.lessons[activeLesson];if(checked){complete();return}if(selection===null){$('#feedback').innerHTML='<div class="feedback incorrect">Selecione uma resposta para continuar.</div>';return}if(selection===l.answer){checked=true;$('#feedback').innerHTML=`<div class="feedback correct">${l.explain}</div>`;b.textContent='Concluir lição ✓';document.querySelectorAll('.answer').forEach(x=>x.disabled=true)}else{$('#feedback').innerHTML='<div class="feedback incorrect">Ainda não! Leia a explicação e tente outra alternativa. Errar faz parte.</div>'}}});
document.addEventListener('submit',e=>{if(e.target.id==='settings'){e.preventDefault();state.name=$('#name').value.trim()||'Aprendiz';state.goal=Number($('#goal').value);save();chrome();$('#saved').textContent='Preferências salvas!'}});
render();
